-- Notifications v2: split destinations (channels) from routing (rules), add a
-- personal preference lane, and put delivery on a durable outbox.
--
-- The DDL block below is generated by `prisma migrate diff`. It is bracketed by
-- the two data steps Prisma cannot generate: stashing the routing that is about
-- to be dropped off notification_channels, and clearing the delivery log so the
-- new NOT NULL columns can be added to it.

-- Stash routing before the columns disappear. Both json columns are normalised
-- to arrays here so nothing downstream can call jsonb_array_length on a scalar
-- (a channel with a JSON `null` scope would otherwise abort the migration).
CREATE TABLE "_notifications_v2_routing" AS
SELECT
    "id" AS "channel_id",
    "organization_id",
    CASE WHEN jsonb_typeof("events") = 'array' THEN "events" ELSE '[]'::jsonb END AS "events",
    CASE WHEN jsonb_typeof("project_ids") = 'array' THEN "project_ids" ELSE '[]'::jsonb END AS "project_ids"
FROM "notification_channels";

-- Deliveries are rebuilt rather than migrated: every new row needs an owning
-- event, and this is a 30-day rolling log behind an early-access flag.
DELETE FROM "notification_deliveries";

