-- Backfill: a channel scoped to N projects becomes N project rules, an
-- unscoped channel becomes one org rule. Event coverage carries over as-is.
INSERT INTO "notification_rules" (
    "id", "organization_id", "channel_id", "scope_type", "scope_id",
    "events", "mode", "enabled", "created_at", "updated_at"
)
SELECT
    gen_random_uuid(), b."organization_id", b."channel_id", 'project', (p.value #>> '{}')::uuid,
    b."events", 'deliver', true, NOW(), NOW()
FROM "_notifications_v2_routing" b
CROSS JOIN LATERAL jsonb_array_elements(b."project_ids") AS p(value)
WHERE jsonb_array_length(b."events") > 0
  AND (p.value #>> '{}') ~ '^[0-9a-fA-F-]{36}$'
  AND EXISTS (SELECT 1 FROM "projects" pr WHERE pr."id" = (p.value #>> '{}')::uuid);

INSERT INTO "notification_rules" (
    "id", "organization_id", "channel_id", "scope_type", "scope_id",
    "events", "mode", "enabled", "created_at", "updated_at"
)
SELECT
    gen_random_uuid(), b."organization_id", b."channel_id", 'org', NULL,
    b."events", 'deliver', true, NOW(), NOW()
FROM "_notifications_v2_routing" b
WHERE jsonb_array_length(b."project_ids") = 0
  AND jsonb_array_length(b."events") > 0;

DROP TABLE "_notifications_v2_routing";
